const getRandomFenFromArray = (fenArrayType: FenArrayType): string => {
  let fenArray: string[];

  switch (fenArrayType) {
    case FenArrayType.WinningArray:
      fenArray = fenWinningArray;
      break;
    case FenArrayType.WinningArrayEndGame:
      fenArray = fenWinningArrayEndGame;
      break;
    case FenArrayType.EqualArray:
      fenArray = fenEqualArray;
      break;
    case FenArrayType.EqualArrayEndGame:
      fenArray = fenEqualArrayEndGame;
      break;
    case FenArrayType.WinningArrayOpening:
      fenArray = fenWinningArrayOpening;
      break;
    case FenArrayType.EqualArrayOpening:
      fenArray = fenEqualArrayOpening;
      break;
  }
  const randomIndex = Math.floor(Math.random() * fenArray.length);
  return fenArray[randomIndex];
};


export enum FenArrayType {
  WinningArray = 'WinningArray',
  WinningArrayEndGame = 'WinningArrayEndGame',
  WinningArrayOpening = 'WinningArrayOpening',
  EqualArray = 'EqualArray',
  EqualArrayEndGame = 'EqualArrayEndGame',
  EqualArrayOpening = 'EqualArrayOpening'
}


function getTurnFromFEN(fen: string): string {
  const turn = fen.split(' ')[1];
  return turn === 'w' ? 'white' : 'black';
}

function clamp(value: number, min: number, max: number): number {
  return Math.min(Math.max(value, min), max);
}

export class Ctrl {
  auth: Auth = new Auth();
  stream?: Stream;
  page: Page = 'home';
  games = new OngoingGames();
  game?: GameCtrl;
  seek?: SeekCtrl;
  challenge?: ChallengeCtrl;
  tv?: TvCtrl;


  level: number = 3;
  clockLimit: number = 10;
  clockIncrement: number = 0;

  constructor(readonly redraw: () => void) {}

  openHome = async () => {
    this.page = 'home';
    if (this.auth.me) {
      await this.stream?.close();
      this.games.empty();
      this.stream = await this.auth.openStream('/api/stream/event', {}, msg => {
        switch (msg.type) {
          case 'gameStart':
            this.games.onStart(msg.game);
            break;
          case 'gameFinish':
            this.games.onFinish(msg.game);
            break;
          default:
            console.warn(`Unprocessed message of type ${msg.type}`, msg);
        }
        this.redraw();
      });
    }
    this.redraw();
  };

  openGame = async (id: string) => {
    this.page = 'game';
    this.game = undefined;
    this.redraw();
    this.game = await GameCtrl.open(this, id);
    this.redraw();
  };

  // playAi = async () => {
  //   this.game = undefined;
  //   this.page = 'game';
  //   this.redraw();
  //
  //   await this.auth.fetchBody('/api/challenge/ai', {
  //     method: 'post',
  //     body: formData({
  //       level: this.level.toString(),
  //       'clock.limit': this.clockLimit.toString(),
  //       'clock.increment': this.clockIncrement.toString()
  //     }),
  //   });
  // };

  playAiFromPosition = async (fenArrayType: FenArrayType) => {
    this.level = clamp(this.level, 1, 8);
    this.clockLimit = clamp(this.clockLimit, 3, 180);
    this.clockIncrement = clamp(this.clockIncrement, 0, 60);

    this.game = undefined;
    this.page = 'game';
    this.redraw();

    try {
      const fen = getRandomFenFromArray(fenArrayType);
      const turn = getTurnFromFEN(fen);
      const response = await this.auth.fetchBody('/api/challenge/ai', {
        method: 'post',
        body: formData({
          level: this.level,
          'clock.limit': this.clockLimit * 60,
          'clock.increment': this.clockIncrement,
          fen: fen,
          color: turn,
        }),
      });

    } catch (error) {
      console.error('Error occurred during API call:', error);
    }
  };


  playPool = async (minutes: number, increment: number) => {
    this.seek = await SeekCtrl.make(
      {
        rated: true,
        time: minutes,
        increment,
      },
      this
    );
    this.page = 'seek';
    this.redraw();
  };

  playMaia = async (minutes: number, increment: number) => {
    this.challenge = await ChallengeCtrl.make(
      {
        username: 'maia1',
        rated: false,
        'clock.limit': minutes * 60,
        'clock.increment': increment,
      },
      this
    );
    this.page = 'challenge';
    this.redraw();
  };

  watchTv = async () => {
    this.page = 'tv';
    this.redraw();
    this.tv = await TvCtrl.open(this);
    this.redraw();
  };
}
